// План specs/admin-access.md, 1.3 (кейс AA-03). Пользователь «בדיקה». Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoSupportConsole } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Support Console — доступ обычного пользователя (#09773471)', () => {
  test('/supportinbox URL variants (trailing slash, query, other case) all redirect to the dashboard #09773471 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    for (const path of ['/supportinbox/', '/supportinbox?x=1', '/SupportInbox']) {
      await test.step(path, async () => {
        await page.goto(path);
        await expect(page).toHaveURL(DASHBOARD_URL);
        await expectNoSupportConsole(page);
      });
    }
  });
});
